        did = _parse_dossier_ref(item.get(key))
        if did is not None:
            return did
    raw = item.get("dossier_id")
    if raw in (None, ""):
        return None
    try:
        return int(raw)
    except (TypeError, ValueError):
        return None

def _coerce_pay_source_float(raw: object, *, default: float = 0.0) -> float:
    if raw in (None, ""):
        return default
    if isinstance(raw, bool):
        raise ValueError("布尔值不是合法比例")
    value = float(raw)
    if not math.isfinite(value):
        raise ValueError("非有限数")
    return value

