    """军队身份别名：id / 军名 / 受控别名。不含驻地/战区/将领上下文。"""
    aliases = [army.id, army.name, compact_name(army.name)]
    for part in re.split(r"\s*/\s*|\s*／\s*", army.name):
        if part.strip():
            aliases.append(part.strip())
    aliases.extend(ARMY_SPECIAL_ALIASES.get(army.id, ()))
    return _unique_aliases(aliases)

def _nonzero_int(raw: object) -> bool:
    if raw in (None, "") or isinstance(raw, (bool, float)):
        return False
    try:
        return int(raw) != 0  # type: ignore[arg-type]
    except (TypeError, ValueError, OverflowError):
        return False

def normalize_evidence(evidence: Any) -> bool:
    if isinstance(evidence, bool):
        return evidence
    if evidence in (None, 0, 1):
        return bool(evidence)
    raise ValueError("evidence 必须是布尔值")

def transport_keys_to_canonical(raw: Mapping[str, object]) -> Dict[str, object]:
    """运输键归一；同义键合并，后写不覆盖已有非空 canonical。"""
    if not isinstance(raw, Mapping):
        raise ValueError("structured decree raw 须为 object")
    out: Dict[str, object] = dict(raw)
    for src, dest in _TRANSPORT_KEY_ALIASES.items():
        if src not in raw:
            continue
        if dest in out and _as_str(out.get(dest)).strip():
            continue
        out[dest] = raw[src]
    if not _as_str(out.get("action_type")).strip():
        for key in ("dossier_action_type", "动作类型"):
            if _as_str(out.get(key)).strip():
                out["action_type"] = out[key]
                break
    return out

def _judge_payload_from_prompt(prompt: object) -> dict:
    """Decode the user JSON exactly as serialized into the real CLI prompt."""
    if not isinstance(prompt, str):
        raise RuntimeError("CLI judge trace has no prompt")
    marker = "【皇帝/输入】\n"
    positions = [index for index in range(len(prompt)) if prompt.startswith(marker, index)]
    if len(positions) != 1:
        raise RuntimeError(f"CLI judge prompt must have one user payload; got {len(positions)}")
    start = positions[0] + len(marker)
    try:
        payload, consumed = json.JSONDecoder().raw_decode(prompt[start:])
    except json.JSONDecodeError as exc:
        raise RuntimeError("CLI judge prompt user payload is not complete JSON") from exc
    remainder = prompt[start + consumed:]
    if not remainder.startswith("\n\n【") or not isinstance(payload, dict):
        raise RuntimeError("CLI judge prompt user payload boundary is invalid")
    return payload

    let dataRaw = "";
    for (const line of block.split("\n")) {
      if (line.startsWith("event: ")) evName = line.slice(7).trim();
      else if (line.startsWith("data: ")) dataRaw += line.slice(6);
    }
    if (!evName || !dataRaw) continue;
    let data: any = {};
    try { data = JSON.parse(dataRaw); } catch { continue; }
    if (evName === "stage") {
      callbacks.onStage?.({
        content: typeof data.content === "string" ? data.content : "",
      });
    } else if (evName === "error") return { kind: "error", data };
    else if (evName === "decisions") return { kind: "decisions", data };
    else if (evName === "done") return { kind: "done", data };
    // thinking/text 等中间事件已随结算进度退役，忽略。
  }
  return null;
}

def _safe_save_name(self, name: str) -> str:
    cleaned = "".join(c for c in name.strip() if c.isalnum() or c in "._-")
    if not cleaned or cleaned.startswith("."):
        raise HTTPException(status_code=400, detail="存档名非法。仅允许字母/数字/._- ")
    return cleaned

