def _oracle_effective_dues(p: Dict[str, Any]) -> Dict[str, float]:
    """oracle 侧折后应得重算：独立于落账的 _effective_dues/haircut_due。
    折发语义同律（floor(Due×bp/10000)、bp=10000 或缺省=无折），但代码自成一路。"""
    raw_h = p.get("due_haircut_bp")
    haircuts: Dict[str, int] = {}
    if raw_h is not None:
        if not isinstance(raw_h, dict):
            raise ValueError(f"param due_haircut_bp 非字典：{raw_h!r}")
        for hk, bp in raw_h.items():
            if hk not in _DUE_KEYS:
                raise ValueError(f"due_haircut_bp 含未知科目 {hk}")
            if isinstance(bp, bool) or not isinstance(bp, int):
                raise ValueError(f"due_haircut_bp[{hk}] 非整数：{bp!r}")
            if not (0 < bp <= 10000):
                raise ValueError(f"due_haircut_bp[{hk}] 须在 (0,10000]：{bp}")
            if bp != 10000:
                haircuts[hk] = bp
    out: Dict[str, float] = {}
    for h in _DUE_KEYS:
        _due = p["Due"]
        d = float(_due.get(h, 0.0)) if isinstance(_due, dict) else 0.0
        bp = haircuts.get(h)
        out[h] = float(math.floor(d * bp / 10000)) if bp is not None else d
    return out

def _norm_int_leaf(v):
    """无损整数串归一（cmr S3 r10,2/2）：strip 后能精确 int 的 str 转 int,
    其余原样返回。无损归一在 cleaner 与此处各一次,
    **判定语义只在 applier**（ship-pre r1 措辞修正:cleaner 残留的同式转换
    与本函数同结果,见 S3 disposition「无害重复」）。"""
    if isinstance(v, str):
        try:
            return int(v.strip())
        except ValueError:
            return v
    return v

def _region_noop_error(region_id: str, row: sqlite3.Row, raw_field: object, value: object) -> str:
    field = REGION_FIELD_ALIASES.get(str(raw_field).strip(), str(raw_field).strip())
    if field == "reason":
        return ""
    if field == "cannon":
        delta = int(value)
        cap = int(row["city_level"]) * 8
        old_value = int(row["cannon"])
        if max(0, min(cap, old_value + delta)) == old_value:
            return _noop_error("region", region_id, raw_field, value)
        return ""
    if field in FISCAL_SCORE_FIELDS:
        fiscal = json.loads(str(row["fiscal"] or "{}"))
        old_value = int(fiscal.get(field, 50))
        delta = int(value)
        net_pct = int(((legacy_mods.get("regions") or {})
                       .get(region_id) or {}).get(field, 0) or 0)
        if net_pct:
            delta = db.apply_legacy_pct(delta, net_pct)
        if max(0, min(100, old_value + delta)) == old_value:
            return _noop_error("region", region_id, raw_field, value)
        return ""
    if field in REGION_SCORE_FIELDS:
        old_value = int(row[field])
        delta = int(value)
        net_pct = int(((legacy_mods.get("regions") or {})
                       .get(region_id) or {}).get(field, 0) or 0)
        if net_pct:
            delta = db.apply_legacy_pct(delta, net_pct)
        if max(0, min(100, old_value + delta)) == old_value:
            return _noop_error("region", region_id, raw_field, value)
        return ""
    if field in REGION_QUANTITY_FIELDS:
        old_value = int(row[field])
        if max(0, old_value + int(value)) == old_value:
            return _noop_error("region", region_id, raw_field, value)
        return ""
    if field in REGION_TEXT_FIELDS:
        return ""
    return ""

