        lines.append(json.dumps(facts, ensure_ascii=False, sort_keys=True))
    return lines

def _feed_identity_names(feed: Mapping[str, Any]) -> List[str]:
    """从 4a 供料里取出该备身份材料的人名（承办人与被查者，去重保序）。

    供料与材料树两处都以这里为准：供料给路径、材料树写正文，名单不同源就会
    出现"给了路径却读不到"或"备了没人指"的对不上。
    """
    names: List[str] = []
    for order in feed.get("active_secret_orders") or []:
        if not isinstance(order, Mapping):
            continue
        for side in ("investigator_identity_materials", "investigation_target_identity_materials"):
            who = str((order.get(side) or {}).get("name") or "").strip()
            if who and who not in names:
                names.append(who)
    return names

def _live(config: Dict[str, int], key: str, turn: int) -> bool:
    """键在位且未到期（伴随键 <完整键名>_until_turn：turn > until → 退出格律）。"""
    if key not in config:
        return False
    until = config.get(str(key) + _UNTIL_SUFFIX)
    if until is not None and turn > int(until):
        return False
    return True

