def project_relation_ledger(db: Any, *, viewer: str | None) -> List[Dict[str, str]]:
    """按授权参数投影关系账读面（#640 单一读取接缝，庭裁 r1 F2）。

    viewer 为必填 keyword-only 参数：全知判官机面（ID-12）必须显式传
    ``viewer=None``；viewer=人名 → 角色视角，参与即知
    （边任一端为该人即可见）。空白（空串/纯空白）viewer 非法，抛 ValueError
    ——绝不静默当全知或当任意角色（fail-closed）。返回形态＝可见边的五字段
    DTO 列表，按 (source, target) 字典序稳定排序。"""
    # 授权边界 fail-closed（冻结票面“非参与者默认不可见”/ADR 0034）：仅
    # viewer is None 可进全知机面；非 None 的空白 viewer 是 malformed 授权
    # 参数，绝不静默当全知或当任意角色，直接拒绝。有效人名一律参与边过滤。
    if viewer is None:
        name = None
    else:
        name = str(viewer).strip()
        if not name:
            raise ValueError(
                "viewer 必须为 None（全知机面）或有效人名；空白授权参数拒绝（fail-closed）"
            )
    pairs = {
        (str(row["source"]), str(row["target"]))
        for row in db.get_relation_summaries()
    }
    for row in db.conn.execute(
        "SELECT DISTINCT source, target FROM relation_edge_events"
    ).fetchall():
        pairs.add((str(row["source"]), str(row["target"])))
    if name is not None:
        pairs = {pair for pair in pairs if name in pair}
    return [_relation_dto(db, source, target) for source, target in sorted(pairs)]

def apply_appointment(
    db: GameDB,
    state: GameState,
    content: GameContent,
    data: Optional[Dict[str, object]] = None,
    llm_config: Optional[LLMConfig] = None,
    commit: bool = True,
) -> Tuple[str, str]:
    """诏书任命共用落地：建档入库，本回合即可召见。"""
    if not data:
        return ("", "")
    if "approved" in data and not bool(data.get("approved")):
        return ("", "")
    name = str(data.get("name") or "").strip()
    office = str(data.get("office") or "").strip()
    if not name or not office:
        return ("", "")
    office = normalize_office(office)
    # 显式名分（office_type ∈ PERSON_TITLE_KINDS）在此建 Character 前就得保住：add_character 的
    # 名分守卫看的是 character.office_type，若这里先被 infer 反推成官职（office='诸生'→'生员'），
    # 守卫永远见不到名分、误建 offices/character_offices（#1059 codex l6h）。
    office_type = resolve_office_type_preserving_title(
        office,
        str(data.get("office_type") or "").strip(),
        "待铨",
        llm_config or db.llm_config,
    )
    if office_type == "后宫":
        return ("", "")

    # ── 查重：精确名 + aliases 命中即拒，不重复建档 ──────────
    # 身份归一认识未仕/宗藩——在册者（含史可法诸生）由此拒新建，走 apply_office_appointment。
    if name in content.characters:
        return ("", "")
    existing = _find_existing_minister(content, name, db)
    if existing is not None:
        return ("", "")

    # ── 职位替换：腾缺现任者 → dismissed ───────────────────────────
    displaced = ""
    replaces = str(data.get("replaces") or "").strip()
    if replaces and replaces in content.characters:
        old = content.characters[replaces]
        if old.status == "active":
            db.set_character_status(
                state, replaces, "dismissed",
                reason=f"{office}改授{name}，原任去职",
                content=content,
                commit=commit,
            )
            displaced = replaces

    person_fields = canonical_new_appointment_person_fields(
        content, data.get("faction"),
    )
    character = Character(
        name=name,
        office=office,
        office_type=office_type,
        aliases=[],
        personal_skills=[],
        power_id="ming",
        status="active",
        office_region=str(
            data.get("office_region") or data.get("region_id") or ""
        ).strip(),
        **person_fields,
    )
    content.characters[name] = character
    db.add_character(state, character, llm_config=llm_config, commit=commit)
    # add_character 已写入并分配 portrait_id，回写到内存对象
    row = db.conn.execute(
        "SELECT portrait_id FROM characters WHERE name=?", (name,)
    ).fetchone()
    if row:
        character.portrait_id = str(row["portrait_id"])
    return (name, displaced)

def summon_character(
    self,
    name_or_text: str,
    current: Optional[Character] = None,
) -> Character:
    """召见人物：只认正式名册。"""
    target = match_minister_from_text(name_or_text, current)
    if target is not None:
        return target
    clean_name = str(name_or_text or "").strip()
    if clean_name in self.content.characters:
        return self.content.characters[clean_name]
    raise ValueError(f"人物未建档：{clean_name}")

def assemble_structured_decree(
    raw: Mapping[str, object],
    *,
    conn: Any = None,
    regions_content: Optional[Mapping[str, Any]] = None,
    validate: bool = True,
) -> Dict[str, object]:
    """原始入口字段 → canonical 结构；不按 target_kind 覆盖已给 locality。"""
    src = transport_keys_to_canonical(raw)
    explicit_scope = _scope_was_explicit(raw) or _scope_was_explicit(src)

    action = _as_str(src.get("action_type") or "").strip()
    target_kind = _as_str(src.get("target_kind") or "").strip()
    target_id = _as_str(src.get("target_id") or "").strip()
    region_id = _as_str(src.get("region_id") or "").strip()
    if target_kind == "region":
        from ming_sim.matching import canonical_region_id_exact

        regions = dict(regions_content or {})
        canonical_target = canonical_region_id_exact(target_id, regions)
        canonical_region = canonical_region_id_exact(region_id or target_id, regions)
        if canonical_target is not None:
            target_id = canonical_target
        if canonical_region is not None:
            region_id = canonical_region

    out: Dict[str, object] = dict(src)
    if action:
        out["action_type"] = action
        if not _as_str(out.get("dossier_action_type")).strip():
            out["dossier_action_type"] = action
    if target_kind:
        out["target_kind"] = target_kind
    if target_id:
        out["target_id"] = target_id

    if explicit_scope:
        out["locality_scope"] = normalize_locality_scope(src.get("locality_scope"))
    else:
        out["locality_scope"] = write_locality_scope_for_target_kind(target_kind)

    if target_kind == "region":
        out["region_id"] = region_id or target_id
    elif region_id:
        out["region_id"] = region_id
    else:
        out.pop("region_id", None)

    cat = _as_str(src.get("transaction_category") or "").strip()
    if cat:
        out["transaction_category"] = cat
    else:
        out.pop("transaction_category", None)

    assignee = _as_str(src.get("assignee_name") or "").strip()
    if action == "assignment" and cat:
        if assignee:
            out["assignee_name"] = assignee
            out["assignee_id"] = assignee
            out["assignee"] = assignee
        else:
            out.pop("assignee_name", None)
            out.pop("assignee_id", None)
            out.pop("assignee", None)
    elif assignee:
        out["assignee_name"] = assignee
        out["assignee_id"] = assignee
        out["assignee"] = assignee

    if validate:
        validate_structured_decree_combination(
            out, conn=conn, regions_content=regions_content,
        )
    return out

def derive_opportunity_band(durable_effects: object) -> str:
    """由 economy/fiscal 流水派生可乘之利档（不依赖未落地 0119）。"""
    rows = list(durable_effects or [])
    if not rows:
        return "none"
    total_abs = 0
    for row in rows:
        if not isinstance(row, dict):
            continue
        for key in ("delta", "amount", "new_value", "old_value"):
            if key in row and row.get(key) is not None:
                try:
                    if key == "old_value":
                        continue
                    total_abs += abs(int(row.get(key) or 0))
                except (TypeError, ValueError):
                    pass
                break
        else:
            # fiscal change: |new-old|
            try:
                nv = int(row.get("new_value") or 0)
                ov = int(row.get("old_value") or 0)
                total_abs += abs(nv - ov)
            except (TypeError, ValueError):
                pass
    if total_abs <= 0:
        return "none"
    if total_abs >= _OPPORTUNITY_HIGH_ABS:
        return "high"
    return "low"

def _env_from_dotenv() -> None:
    env_path = ROOT / ".env"
    if env_path.exists():
        for line in env_path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            key, _, value = line.partition("=")
            os.environ.setdefault(key.strip(), value.strip().strip('"').strip("'"))
    for src, dst in (
        ("CLI_API_KEY", "OPENAI_API_KEY"),
        ("CLI_BASE_URL", "OPENAI_BASE_URL"),
        ("CLI_MODEL", "OPENAI_MODEL"),
    ):
        if os.environ.get(src) and not os.environ.get(dst):
            os.environ[dst] = os.environ[src]

  let event = "message";
  const dataLines: string[] = [];
  for (const line of lines) {
    if (line.startsWith("event:")) {
      event = line.slice(6).trim();
    } else if (line.startsWith("data:")) {
      dataLines.push(line.slice(5).trimStart());
    }
  }
  if (!dataLines.length) return null;
  return { event, data: dataLines.join("\n") };
};

