    # 旧副本多一个「已」字，offstage 产「已尚未登场」；后宫仍由 can_summon 放行
    # （不拒 office_type=后宫，嫔妃 chat 复用本端点）。
    ok, reason = get_game().session.can_summon(character)
    if not ok:
        raise HTTPException(status_code=409, detail=(reason or "").strip())
